#!/usr/bin/env python3
"""
Multi-API Benchmark Harness with Streaming TTFT Measurement

Supports Chat Completions API and Responses API formats.
Measures Time-To-First-Token (TTFT) via SSE streaming.
Uses only Python stdlib.
"""

import argparse
import json
import os
import sys
import time
import uuid
import urllib.request
import urllib.error
import ssl
from datetime import datetime, timezone
from concurrent.futures import ThreadPoolExecutor, as_completed
from typing import Any, Optional


BENCHMARK_PROMPT = "Reply with exactly one sentence about the color blue."


def build_request_body(model_config: dict) -> dict:
    """Build the appropriate request body based on api_type."""
    api_type = model_config["api_type"]
    model_id = model_config["id"]
    temperature = model_config.get("temperature", 0.7)
    max_tokens = model_config.get("max_tokens", 100)

    if api_type == "chat_completions":
        return {
            "model": model_id,
            "messages": [
                {"role": "user", "content": BENCHMARK_PROMPT}
            ],
            "stream": True,
            "temperature": temperature,
            "max_tokens": max_tokens,
        }
    elif api_type == "responses":
        return {
            "model": model_id,
            "input": BENCHMARK_PROMPT,
            "stream": True,
            "temperature": temperature,
            "max_tokens": max_tokens,
        }
    else:
        raise ValueError(f"Unknown api_type: {api_type}")


def get_api_endpoint(model_config: dict) -> str:
    """Get the full API endpoint URL."""
    base_url = model_config["base_url"].rstrip("/")
    api_type = model_config["api_type"]

    if api_type == "chat_completions":
        return f"{base_url}/v1/chat/completions"
    elif api_type == "responses":
        return f"{base_url}/v1/responses"
    else:
        raise ValueError(f"Unknown api_type: {api_type}")


def get_api_key(model_config: dict) -> Optional[str]:
    """Retrieve the API key from environment variables."""
    env_var = model_config.get("api_key_env")
    if env_var:
        key = os.environ.get(env_var)
        if not key:
            raise ValueError(
                f"Environment variable '{env_var}' not set for model '{model_config['id']}'"
            )
        return key
    return None


def extract_content_from_sse_data(api_type: str, data_obj: dict) -> Optional[str]:
    """
    Extract text content from a parsed SSE data JSON object.
    Returns the content string if present and non-empty, else None.
    """
    if api_type == "chat_completions":
        # Format: {"choices": [{"delta": {"content": "..."}}]}
        choices = data_obj.get("choices")
        if choices and len(choices) > 0:
            delta = choices[0].get("delta", {})
            content = delta.get("content")
            if content is not None and content != "":
                return content
    elif api_type == "responses":
        # Format: {"type": "content_block_delta", "delta": {"text": "..."}}
        # We also handle {"type": "response.output_text.delta", "delta": "..."}
        event_type = data_obj.get("type", "")
        if event_type in ("content_block_delta",):
            delta = data_obj.get("delta", {})
            if isinstance(delta, dict):
                text = delta.get("text")
                if text is not None and text != "":
                    return text
        # Also handle OpenAI responses API format variations
        elif event_type in ("response.output_text.delta",):
            delta = data_obj.get("delta")
            if isinstance(delta, str) and delta != "":
                return delta
            elif isinstance(delta, dict):
                text = delta.get("text")
                if text is not None and text != "":
                    return text

    return None


def parse_sse_lines(raw_line: str):
    """
    Parse a raw chunk of bytes from the stream into SSE data strings.
    Yields each data payload string (after 'data: ' prefix).
    """
    line = raw_line.strip()
    if line.startswith("data: "):
        data_str = line[6:]  # Remove 'data: ' prefix
        if data_str.strip() == "[DONE]":
            return  # Signal end of stream
        yield data_str


def benchmark_model(model_config: dict, timeout: int) -> dict:
    """
    Benchmark a single model by sending a streaming request and measuring TTFT.
    Returns a result dictionary.
    """
    model_id = model_config["id"]
    api_type = model_config["api_type"]

    result = {
        "model_id": model_id,
        "api_type": api_type,
        "status": "error",
        "ttft_ms": None,
        "total_ms": None,
        "first_token": None,
        "full_response": None,
        "error": None,
    }

    try:
        # Build request
        endpoint = get_api_endpoint(model_config)
        api_key = get_api_key(model_config)
        body = build_request_body(model_config)
        body_bytes = json.dumps(body).encode("utf-8")

        # Build urllib request
        req = urllib.request.Request(
            endpoint,
            data=body_bytes,
            method="POST",
        )
        req.add_header("Content-Type", "application/json")
        req.add_header("Accept", "text/event-stream")
        if api_key:
            req.add_header("Authorization", f"Bearer {api_key}")

        # Create an SSL context that works broadly
        ssl_context = ssl.create_default_context()

        # Record start time immediately before request
        t_start = time.monotonic()

        response = urllib.request.urlopen(
            req,
            timeout=timeout,
            context=ssl_context,
        )

        # Parse SSE stream
        t_first_token = None
        first_token = None
        content_chunks = []
        buffer = ""

        try:
            while True:
                # Read data in chunks
                chunk = response.read(1)
                if not chunk:
                    break

                try:
                    buffer += chunk.decode("utf-8")
                except UnicodeDecodeError:
                    # Read more bytes for multi-byte characters
                    extra = response.read(3)
                    if extra:
                        buffer += (chunk + extra).decode("utf-8", errors="replace")
                    continue

                # Process complete lines
                while "\n" in buffer:
                    line, buffer = buffer.split("\n", 1)
                    line = line.strip()

                    if not line:
                        continue

                    if line.startswith("data: "):
                        data_str = line[6:].strip()

                        if data_str == "[DONE]":
                            break

                        try:
                            data_obj = json.loads(data_str)
                        except json.JSONDecodeError:
                            continue

                        content = extract_content_from_sse_data(api_type, data_obj)
                        if content is not None:
                            if t_first_token is None:
                                t_first_token = time.monotonic()
                                first_token = content
                            content_chunks.append(content)
        except Exception:
            # If we already got some data, continue to record results
            pass
        finally:
            response.close()

        t_end = time.monotonic()

        total_ms = (t_end - t_start) * 1000.0

        if t_first_token is not None:
            ttft_ms = (t_first_token - t_start) * 1000.0
            full_response = "".join(content_chunks)
            result.update({
                "status": "ok",
                "ttft_ms": round(ttft_ms, 1),
                "total_ms": round(total_ms, 1),
                "first_token": first_token,
                "full_response": full_response,
                "error": None,
            })
        else:
            result.update({
                "status": "error",
                "total_ms": round(total_ms, 1),
                "error": "No content tokens received in stream",
            })

    except urllib.error.HTTPError as e:
        t_end = time.monotonic()
        error_body = ""
        try:
            error_body = e.read().decode("utf-8", errors="replace")[:500]
        except Exception:
            pass
        result.update({
            "total_ms": round((t_end - t_start) * 1000.0, 1) if 't_start' in dir() else None,
            "error": f"HTTP {e.code}: {e.reason}. {error_body}".strip(),
        })

    except urllib.error.URLError as e:
        t_end = time.monotonic()
        reason = str(e.reason) if hasattr(e, 'reason') else str(e)
        if "timed out" in reason.lower() or "timeout" in reason.lower():
            result["error"] = f"Connection timeout after {timeout}s"
        else:
            result["error"] = f"URL error: {reason}"
        try:
            result["total_ms"] = round((t_end - t_start) * 1000.0, 1)
        except NameError:
            pass

    except TimeoutError:
        t_end = time.monotonic()
        result["error"] = f"Connection timeout after {timeout}s"
        try:
            result["total_ms"] = round((t_end - t_start) * 1000.0, 1)
        except NameError:
            pass

    except ValueError as e:
        result["error"] = f"Configuration error: {str(e)}"

    except Exception as e:
        t_end = time.monotonic()
        result["error"] = f"{type(e).__name__}: {str(e)}"
        try:
            result["total_ms"] = round((t_end - t_start) * 1000.0, 1)
        except NameError:
            pass

    return result


def run_benchmark(config: dict, timeout: int, workers: int) -> dict:
    """Run the benchmark across all configured models."""
    models = config.get("models", [])
    if not models:
        print("No models configured in config file.", file=sys.stderr)
        sys.exit(1)

    run_id = str(uuid.uuid4())
    timestamp = datetime.now(timezone.utc).isoformat()

    results = []

    print(f"Benchmark run: {run_id}")
    print(f"Models to test: {len(models)}")
    print(f"Workers: {workers}")
    print(f"Timeout: {timeout}s")
    print(f"Prompt: \"{BENCHMARK_PROMPT}\"")
    print("-" * 60)

    if workers <= 1:
        # Sequential execution
        for model_config in models:
            model_id = model_config.get("id", "unknown")
            print(f"Testing {model_id}...", end=" ", flush=True)
            result = benchmark_model(model_config, timeout)
            results.append(result)
            if result["status"] == "ok":
                print(f"OK (TTFT: {result['ttft_ms']}ms, Total: {result['total_ms']}ms)")
            else:
                print(f"ERROR: {result['error']}")
    else:
        # Parallel execution
        future_to_model = {}
        with ThreadPoolExecutor(max_workers=workers) as executor:
            for model_config in models:
                future = executor.submit(benchmark_model, model_config, timeout)
                future_to_model[future] = model_config.get("id", "unknown")

            for future in as_completed(future_to_model):
                model_id = future_to_model[future]
                try:
                    result = future.result()
                except Exception as e:
                    result = {
                        "model_id": model_id,
                        "api_type": "unknown",
                        "status": "error",
                        "ttft_ms": None,
                        "total_ms": None,
                        "first_token": None,
                        "full_response": None,
                        "error": f"Worker exception: {type(e).__name__}: {str(e)}",
                    }
                results.append(result)
                if result["status"] == "ok":
                    print(f"{model_id}: OK (TTFT: {result['ttft_ms']}ms, Total: {result['total_ms']}ms)")
                else:
                    print(f"{model_id}: ERROR: {result['error']}")

    # Reorder results to match config order
    if workers > 1:
        model_order = [m.get("id", "unknown") for m in models]
        result_map = {r["model_id"]: r for r in results}
        ordered_results = []
        for mid in model_order:
            if mid in result_map:
                ordered_results.append(result_map[mid])
        # Add any results not in config order (shouldn't happen)
        seen = set(model_order)
        for r in results:
            if r["model_id"] not in seen:
                ordered_results.append(r)
        results = ordered_results

    # Build summary
    ok_results = [r for r in results if r["status"] == "ok"]
    error_count = len(results) - len(ok_results)

    summary = {
        "total": len(results),
        "ok": len(ok_results),
        "errors": error_count,
        "avg_ttft_ms": None,
        "fastest_model": None,
        "slowest_model": None,
    }

    if ok_results:
        ttft_values = [r["ttft_ms"] for r in ok_results if r["ttft_ms"] is not None]
        if ttft_values:
            summary["avg_ttft_ms"] = round(sum(ttft_values) / len(ttft_values), 1)
            fastest = min(ok_results, key=lambda r: r["ttft_ms"] if r["ttft_ms"] is not None else float('inf'))
            slowest = max(ok_results, key=lambda r: r["ttft_ms"] if r["ttft_ms"] is not None else 0)
            summary["fastest_model"] = fastest["model_id"]
            summary["slowest_model"] = slowest["model_id"]

    output = {
        "run_id": run_id,
        "timestamp": timestamp,
        "prompt": BENCHMARK_PROMPT,
        "results": results,
        "summary": summary,
    }

    return output


def main():
    parser = argparse.ArgumentParser(
        description="Multi-API LLM Benchmark Harness with Streaming TTFT Measurement"
    )
    parser.add_argument(
        "--config",
        required=True,
        help="Path to model config JSON file",
    )
    parser.add_argument(
        "--output",
        default="benchmark_results.json",
        help="Output file path (default: benchmark_results.json)",
    )
    parser.add_argument(
        "--timeout",
        type=int,
        default=30,
        help="Per-model timeout in seconds (default: 30)",
    )
    parser.add_argument(
        "--workers",
        type=int,
        default=1,
        help="Number of parallel workers (default: 1)",
    )

    args = parser.parse_args()

    # Load config
    try:
        with open(args.config, "r", encoding="utf-8") as f:
            config = json.load(f)
    except FileNotFoundError:
        print(f"Error: Config file not found: {args.config}", file=sys.stderr)
        sys.exit(1)
    except json.JSONDecodeError as e:
        print(f"Error: Invalid JSON in config file: {e}", file=sys.stderr)
        sys.exit(1)

    # Validate config
    if "models" not in config or not isinstance(config["models"], list):
        print("Error: Config must contain a 'models' array.", file=sys.stderr)
        sys.exit(1)

    for i, model in enumerate(config["models"]):
        if "id" not in model:
            print(f"Error: Model at index {i} missing 'id' field.", file=sys.stderr)
            sys.exit(1)
        if "api_type" not in model:
            print(f"Error: Model '{model['id']}' missing 'api_type' field.", file=sys.stderr)
            sys.exit(1)
        if model["api_type"] not in ("chat_completions", "responses"):
            print(
                f"Error: Model '{model['id']}' has invalid api_type '{model['api_type']}'. "
                f"Must be 'chat_completions' or 'responses'.",
                file=sys.stderr,
            )
            sys.exit(1)
        if "base_url" not in model:
            print(f"Error: Model '{model['id']}' missing 'base_url' field.", file=sys.stderr)
            sys.exit(1)

    # Run benchmark
    output = run_benchmark(config, args.timeout, args.workers)

    # Save results
    try:
        with open(args.output, "w", encoding="utf-8") as f:
            json.dump(output, f, indent=2, ensure_ascii=False)
        print("-" * 60)
        print(f"Results saved to: {args.output}")
    except IOError as e:
        print(f"Error writing output file: {e}", file=sys.stderr)
        # Print to stdout as fallback
        print(json.dumps(output, indent=2, ensure_ascii=False))

    # Print summary
    summary = output["summary"]
    print(f"\nSummary:")
    print(f"  Total models: {summary['total']}")
    print(f"  Successful:   {summary['ok']}")
    print(f"  Errors:       {summary['errors']}")
    if summary["avg_ttft_ms"] is not None:
        print(f"  Avg TTFT:     {summary['avg_ttft_ms']}ms")
        print(f"  Fastest:      {summary['fastest_model']}")
        print(f"  Slowest:      {summary['slowest_model']}")


if __name__ == "__main__":
    main()
